	base := rev(t, repo, "HEAD")
	for i := range files {
		write(t, repo, fmt.Sprintf("mod%03d.py", i), fmt.Sprintf("def handler%03d(value, extra=None):\n    return value\n", i))
	}
	git(t, repo, "add", ".")
	git(t, repo, "commit", "-m", "change")
	head := rev(t, repo, "HEAD")

